CREATE TABLE `refund_reasons` (
    `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    `type` VARCHAR(255) NOT NULL, 
    `reason` VARCHAR(255) NOT NULL,
    `status` INT(2) NOT NULL DEFAULT 1 ,
    `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
    `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
);

CREATE TABLE `refund_reason_translations` (
    `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    `refund_reason_id` INT(11) NOT NULL, 
    `reason` VARCHAR(255) NOt NULL,
    `lang` varchar(100) NOT NULL,
    `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
    `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
);

ALTER TABLE `order_details`
ADD COLUMN `dispute_refund_days` INT(11) NOT NULL DEFAULT 0
AFTER `refund_days`;

ALTER TABLE `refund_requests`
ADD COLUMN `refund_code` VARCHAR(100) NULL AFTER `id`,
ADD UNIQUE (`refund_code`),
ADD COLUMN `dispute_reason` LONGTEXT NULL AFTER `reason`,
ADD COLUMN `dispute_refund_status` INT(2) NULL AFTER `dispute_reason`,
ADD COLUMN `dispute_images` VARCHAR(255) NULL AFTER `dispute_refund_status`,
ADD COLUMN `admin_dispute_reject_reason` VARCHAR(255) NULL AFTER `dispute_images`,
ADD COLUMN `dispute_refund_created_at` timestamp NULL AFTER `admin_dispute_reject_reason`,
ADD COLUMN `refund_approval_datatime` timestamp NULL AFTER `dispute_refund_created_at`,
ADD COLUMN `dispute_refund_approval_datatime` timestamp NULL AFTER `refund_approval_datatime`,
ADD COLUMN `seller_refund_approval_datatime` timestamp NULL AFTER `dispute_refund_approval_datatime`,
ADD COLUMN `dispute_photo` VARCHAR(255) NULL AFTER `seller_refund_approval_datatime`,
ADD COLUMN `dispute_admin_approval` INT(2) DEFAULT 0 NULL AFTER `dispute_photo`;

UPDATE refund_requests
SET 
    refund_approval_datatime = updated_at,
    seller_refund_approval_datatime = updated_at
WHERE 
    refund_approval_datatime IS NULL
    AND seller_refund_approval_datatime IS NULL;


    UPDATE `refund_requests`
        SET `preferred_payment_channel` = 'wallet'
        WHERE `preferred_payment_channel` IS NULL;
    
UPDATE refund_requests
SET refund_code = CONCAT(
    DATE_FORMAT(NOW(), '%Y%m%d-%H%i%s'),
    id,
    FLOOR(10 + (RAND() * 90))
)
WHERE refund_code IS NULL;

CREATE TABLE `offline_payout_methods` (
    `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    `type` VARCHAR(255) NOT NULL, 
    `name` VARCHAR(255) NOT NULL, 
    `image` VARCHAR(255) NULL,
    `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
    `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
);

